$stmt=$pdo->prepare("SELECT COUNT(*) FROM saved_jobs WHERE user_id=?");$stmt->execute([$user['id']]);$savedCount=(int)$stmt->fetchColumn();
$stmt=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE -amount END),0) FROM transactions WHERE user_id=? AND MONTH(transaction_date)=MONTH(CURRENT_DATE()) AND YEAR(transaction_date)=YEAR(CURRENT_DATE())");$stmt->execute([$user['id']]);$balance=(float)$stmt->fetchColumn();
$stmt=$pdo->prepare("SELECT a.status,a.created_at,j.title,j.id AS job_id,u.company_name FROM applications a JOIN jobs j ON j.id=a.job_id JOIN users u ON u.id=j.employer_id WHERE a.user_id=? ORDER BY a.created_at DESC LIMIT 5");$stmt->execute([$user['id']]);$applications=$stmt->fetchAll();
include __DIR__.'/includes/header.php';
?>
